/* Precise impacts, elevated combat, dangerous abominations and relic trading. */
'use strict';
const B7={makeEntity,makeSave,restoreWorld,vendorRecord,inventoryItems,refreshTradeHeader,createUI,showTitle,propIndex,placeProp,removeProp,validSave};
const COLLISIONS={scene:null,dirty:true,buckets:new Map(),dynamicTime:-1,dynamic:[]};
MATERIALS.metal={hp:125,loot:.35,color:'#859599'};Object.assign(PROP_MATERIAL,{sarcophagus:'stone',arch:'stone',brazier:'metal',anvil:'metal',orrery:'metal'});
function markCollisionDirty(){COLLISIONS.dirty=true;COLLISIONS.dynamicTime=-1;}
function bucketBounds(map,entry,min=entry.min,max=entry.max){for(let x=Math.floor(min.x/5);x<=Math.floor(max.x/5);x++)for(let z=Math.floor(min.z/5);z<=Math.floor(max.z/5);z++){const key=x+','+z;if(!map.has(key))map.set(key,[]);map.get(key).push(entry);}}
propIndex=function(){propBuckets.clear();for(const p of destructibles.values())if(!p.dead)bucketBounds(propBuckets,p);markCollisionDirty();};
placeProp=function(...args){const m=B7.placeProp(...args);markCollisionDirty();return m;};
removeProp=function(...args){const result=B7.removeProp(...args);markCollisionDirty();return result;};
function solidMesh(m){return !!m&& !m.isDisposed()&&m.isEnabled()&&m.getTotalVertices?.()>0&&m.isVisible!==false&&m.material?.alpha!==0&&(m.material?.alpha??1)>=.9;}
function meshEntries(root,prop=null){const meshes=[root,...(root.getChildMeshes?.()||[])],out=[];for(const mesh of meshes)if(solidMesh(mesh)){mesh.computeWorldMatrix(true);const b=mesh.getBoundingInfo().boundingBox;out.push({mesh,prop,min:b.minimumWorld.clone(),max:b.maximumWorld.clone()});}return out;}
function rebuildCollisionIndex(){COLLISIONS.scene=scene;COLLISIONS.buckets.clear();const seen=new Set();for(const root of world.props){if(seen.has(root)||root.isDisposed())continue;seen.add(root);const prop=root.metadata?.destructible;if(prop?.dead)continue;for(const e of meshEntries(root,prop))bucketBounds(COLLISIONS.buckets,e);}if(inCrucible())for(const box of CRUCIBLE.collisionBoxes||[])bucketBounds(COLLISIONS.buckets,box);for(const m of world.chunks)if(m.name==='suspended crown band')for(const e of meshEntries(m))bucketBounds(COLLISIONS.buckets,e);COLLISIONS.dirty=false;COLLISIONS.dynamicTime=-1;}
function segmentBox(a,b,min,max,pad=0){let near=0,far=1;for(const k of['x','y','z']){const delta=b[k]-a[k];if(Math.abs(delta)<1e-10){if(a[k]<min[k]-pad||a[k]>max[k]+pad)return null;continue;}let t0=(min[k]-pad-a[k])/delta,t1=(max[k]+pad-a[k])/delta;if(t0>t1)[t0,t1]=[t1,t0];near=Math.max(near,t0);far=Math.min(far,t1);if(near>far)return null;}return near;}
function terrainImpact(a,b){const delta=b.subtract(a),length=delta.length();if(length<1e-9)return solidWorld(a.x,a.y,a.z)?0:null;if(G.mode==='dungeon'&&!inCrucible()){
 const cell={x:Math.floor(a.x/VS),y:Math.floor(a.y/VS),z:Math.floor(a.z/VS)},step={},next={},stride={};for(const k of['x','y','z']){step[k]=Math.sign(delta[k]);next[k]=step[k]?( (cell[k]+(step[k]>0?1:0))*VS-a[k])/delta[k]:Infinity;stride[k]=step[k]?VS/Math.abs(delta[k]):Infinity;}let t=0;for(let i=0;i<4096&&t<=1;i++){if(solidWorld((cell.x+.5)*VS,(cell.y+.5)*VS,(cell.z+.5)*VS))return Math.max(0,t);const advance=Math.min(next.x,next.y,next.z);if(!Number.isFinite(advance)||advance>1)return null;for(const k of['x','y','z'])if(next[k]<=advance+1e-10){cell[k]+=step[k];next[k]+=stride[k];}t=advance;}return null;
 }
 // Outdoor ground and the Crucible shell are continuous solid volumes.
 const steps=Math.max(1,Math.ceil(length/.1));for(let i=0;i<=steps;i++){const t=i/steps,p=a.add(delta.scale(t));if(solidWorld(p.x,p.y,p.z)){let low=Math.max(0,(i-1)/steps),high=t;for(let j=0;j<8;j++){const mid=(low+high)/2,q=a.add(delta.scale(mid));if(solidWorld(q.x,q.y,q.z))high=mid;else low=mid;}return high;}}return null;
}
function traceEnvironment(a,b){if(COLLISIONS.scene!==scene||COLLISIONS.dirty)rebuildCollisionIndex();const delta=b.subtract(a),length=delta.length();if(length<1e-8)return null;let best=terrainImpact(a,b),result=best===null?null:{t:best,terrain:true};const candidates=new Set();const min=V3(Math.min(a.x,b.x)-.05,Math.min(a.y,b.y)-.05,Math.min(a.z,b.z)-.05),max=V3(Math.max(a.x,b.x)+.05,Math.max(a.y,b.y)+.05,Math.max(a.z,b.z)+.05);for(let x=Math.floor(min.x/5);x<=Math.floor(max.x/5);x++)for(let z=Math.floor(min.z/5);z<=Math.floor(max.z/5);z++)for(const e of COLLISIONS.buckets.get(x+','+z)||[])candidates.add(e);
 if(COLLISIONS.dynamicTime!==G.time){COLLISIONS.dynamicTime=G.time;COLLISIONS.dynamic=[];for(const c of G.crates)if(c.mesh&&!c.mesh.isDisposed())COLLISIONS.dynamic.push(...meshEntries(c.mesh));for(const v of collisionMerchants())if(v?.rig?.root)COLLISIONS.dynamic.push(...meshEntries(v.rig.root));}for(const e of COLLISIONS.dynamic)candidates.add(e);
 const ray=new BABYLON.Ray(a,delta.scale(1/length),length);for(const e of candidates){if(e.prop?.dead||e.mesh?.isDisposed())continue;const broad=segmentBox(a,b,e.min,e.max,.025);if(broad===null||best!==null&&broad>best)continue;let t;if(e.inverse)t=segmentBox(BABYLON.Vector3.TransformCoordinates(a,e.inverse),BABYLON.Vector3.TransformCoordinates(b,e.inverse),e.localMin,e.localMax);else{const pick=ray.intersectsMesh(e.mesh,false);t=pick.hit&&pick.distance<=length+.0001?pick.distance/length:null;}if(t!==null&&(best===null||t<best)){best=t;result={t,prop:e.prop,mesh:e.mesh,structural:!e.prop};}}
 if(result)result.point=a.add(delta.scale(result.t));return result;
}
function entityHitVolume(e){const h=e.rig.height||1;let center=e.pos.y+h*.5;if(e.spec?.fly){const node=e.rig.nodes.body;node?.computeWorldMatrix(true);center=node?node.getAbsolutePosition().y:e.pos.y;}return{minY:e.spec?.fly?center-Math.max(.18,h*.5):e.pos.y-.1,maxY:e.spec?.fly?center+Math.max(.18,h*.5):e.pos.y+h+.12,radius:(e.radius||.4)+.1};}
function traceEntity(a,b,e){const v=entityHitVolume(e),dx=b.x-a.x,dz=b.z-a.z,ox=a.x-e.pos.x,oz=a.z-e.pos.z,A=dx*dx+dz*dz,B=2*(ox*dx+oz*dz),C=ox*ox+oz*oz-v.radius*v.radius;let near=0,far=1;if(A<1e-12){if(C>0)return null;}else{const disc=B*B-4*A*C;if(disc<0)return null;near=Math.max(near,(-B-Math.sqrt(disc))/(2*A));far=Math.min(far,(-B+Math.sqrt(disc))/(2*A));}const dy=b.y-a.y;if(Math.abs(dy)<1e-12){if(a.y<v.minY||a.y>v.maxY)return null;}else{let n=(v.minY-a.y)/dy,f=(v.maxY-a.y)/dy;if(n>f)[n,f]=[f,n];near=Math.max(near,n);far=Math.min(far,f);}return near<=far&&far>=0&&near<=1?Math.max(0,near):null;}
function aimPointFromCamera(distance=100){const ray=cam.getForwardRay(),a=cam.position,b=a.add(ray.direction.scale(distance));let hit=traceEnvironment(a,b);for(const e of G.enemies){if(e.dead||e.passive)continue;const t=traceEntity(a,b,e);if(t!==null&&(!hit||t<hit.t))hit={t,point:a.add(b.subtract(a).scale(t)),entity:e};}return hit?.point||b;}
function impactEnvironment(hit,p){if(hit.prop&&!hit.prop.dead)damageProp(hit.prop,Math.max(hit.prop.hp,p.dmg||0),hit.point,p.element||'projectile');spark(hit.point,p.color||'#c4baa6',7);}
function meleeImpactVisible(att,point){const from=att.pos.add(V3(0,Math.min(1.4,(att.rig.height||1.8)*.65),0)),hit=traceEnvironment(from,point);return !hit||hit.t>.98;}
function stepProjectile(p,dt){if(!p||p.mesh.isDisposed())return;p.life-=dt;const from=p.mesh.position.clone(),to=from.add(p.vel.scale(dt));let hit=traceEnvironment(from,to);const targets=p.fromPlayer?G.enemies:[player];for(const e of targets){if(e.dead||e.passive||p.fromPlayer&&e.isPlayer)continue;const t=traceEntity(from,to,e);if(t!==null&&(!hit||t<hit.t-.000001))hit={t,entity:e,point:from.add(to.subtract(from).scale(t))};}p.mesh.position.copyFrom(hit?.point||to);if(hit){if(hit.entity){const e=hit.entity;if(p.fromPlayer){hitEnemy(e,p.dmg,false,player.pos);if(p.element==='frost')e.status.chill=3;if(p.element==='fire')e.status.burn=3;applyProjectileElement(e,p);}else hitPlayer(p.dmg,hit.point,'projectile');spark(hit.point,p.color,5);}else impactEnvironment(hit,p);}else{emitEnergyTrail(p,from,to,dt);}if(hit||p.life<=0){killNode(p.mesh);const i=G.projectiles.indexOf(p);if(i>=0)G.projectiles.splice(i,1);}}
// Compatibility for direct material contact; hostile shots interact identically.
hitDestructibleProjectile=function(point,p){for(const prop of new Set(nearby(propBuckets,point.x,point.z)))if(!prop.dead&&pointInProp(prop,point,.035)){impactEnvironment({prop,point},p);return true;}return false;};
function specialDamage(e,multiplier=1){return e.dmg*multiplier*(e.spec.abomination?1.8:1);}
makeEntity=function(...args){const e=B7.makeEntity(...args);if(e.spec.abomination){e.dmg*=1.9;e.combatRevision=1;}return e;};
function makePremiumStock(config={}){vendorSetFilter=null;return preserveRandom(()=>{SEED=(config.seed??(G.levelSeed^0x73ab129))|0;const stock=[],families=Object.keys(ARMOR_SETS),baseLevel=config.level??Math.max(G.depth*2+10,player.level*2+8,...Object.values(player.gear).filter(Boolean).map(it=>it.ilvl+2)),shuffle=a=>{for(let i=a.length-1;i>0;i--){const j=ri(0,i);[a[i],a[j]]=[a[j],a[i]];}return a;},add=(slot,kind,rarity)=>{const it=makeItem(slot,baseLevel+ri(0,5),rarity??config.rarity??(rnd()<.35?5:4),kind),row={item:it,price:Math.round(sellValue(it)*(config.markup??(it.rarity===5?2.9:2.5))),sold:false};stock.push(row);return row;};vendor.stockRevision=2;vendor.collections=[];
 for(let group=0;group<3;group++){const keys=shuffle(Object.keys(WEAPONS).filter(k=>{const w=WEAPONS[k];return(w.ranged||w.magic?2:w.hands===2?1:0)===group;}));for(const key of keys.slice(0,12))add('weapon',key);}
 for(const slot of SLOTS.filter(s=>s!=='weapon'))for(const family of shuffle([...families]).slice(0,5))add(slot,family);
 const chance=rnd(),count=config.collections??(chance<.2?2:chance<.7?1:0);for(const family of shuffle([...families]).slice(0,count)){const rarity=config.rarity??(rnd()<.4?5:4),ids=[];for(const slot of SLOTS.filter(s=>s!=='weapon'))ids.push(add(slot,family,rarity).item.id);vendor.collections.push({family,name:ARMOR_SETS[family].name,ids});}return stock;});}
function collectionRows(collection){return collection.ids.map(id=>vendor.stock.find(r=>r.item.id===id)).filter(Boolean);}
function buyVendorCollection(index){const set=vendor?.collections?.[index];if(!tradeAllowed()||!set)return false;const rows=collectionRows(set);if(rows.length!==6||rows.some(r=>r.sold))return false;const price=Math.round(rows.reduce((n,r)=>n+r.price,0)*.85);if(player.gold<price)return false;player.gold-=price;for(const r of rows){r.sold=true;player.bag.push(r.item);}saveGame(true);refreshInv();showDetail(null);sound('loot');$('tradeStatus').textContent='Purchased the complete '+set.name+' collection · six pieces in your satchel.';return true;}
let vendorSetFilter=null;
inventoryItems=function(){const items=B7.inventoryItems();return TRADE.active&&TRADE.side==='vendor'&&vendorSetFilter?items.filter(it=>it.armorSet===vendorSetFilter):items;};
refreshTradeHeader=function(){B7.refreshTradeHeader();const el=$('collectionOffers');el.hidden=!(TRADE.active&&TRADE.side==='vendor');if(el.hidden)return;el.innerHTML='';const reset=document.createElement('button');reset.textContent=vendorSetFilter?'Show all wares':'Legendary & Mythic wares';reset.disabled=!vendorSetFilter;reset.onclick=()=>{vendorSetFilter=null;bagFilter='all';bagPage=0;selected=null;refreshInv();showDetail(null);};el.appendChild(reset);for(const [i,set]of(vendor.collections||[]).entries()){const rows=collectionRows(set),complete=rows.length===6&&rows.every(r=>!r.sold),price=Math.round(rows.reduce((n,r)=>n+r.price,0)*.85),box=document.createElement('div');box.className='collectionOffer';const inspect=document.createElement('button');inspect.textContent=set.name+' · '+rows.filter(r=>!r.sold).length+'/6';inspect.onclick=()=>{vendorSetFilter=set.family;bagFilter='all';bagPage=0;selected=null;refreshInv();showDetail(null);};const buy=document.createElement('button');buy.textContent=complete?'Buy full set · '+price+' gold · 15% off':'Set partly sold';buy.disabled=!complete||player.gold<price;buy.onclick=()=>buyVendorCollection(i);box.appendChild(inspect);box.appendChild(buy);el.appendChild(box);}};
createUI=function(){B7.createUI();$('tradeBar').insertAdjacentHTML('beforeend','<div id="collectionOffers" hidden aria-label="Full armor collection offers"></div>');};
vendorRecord=function(){const d=B7.vendorRecord();if(d){d.stockRevision=vendor.stockRevision||2;d.collections=(vendor.collections||[]).map(c=>({...c,ids:[...c.ids]}));d.pastPurchases=vendor.pastPurchases||0;}return d;};
makeSave=function(){const d=B7.makeSave();d.build='7 · Relics & Reckoning';for(const row of d.enemies){const e=G.enemies.find(e=>e.eid===row.eid);if(e?.spec.abomination)row.combatRevision=1;}return d;};
restoreWorld=function(d){B7.restoreWorld(d);for(const saved of d.enemies){const e=G.enemies.find(q=>q.eid===saved.eid);if(e?.spec.abomination&&saved.combatRevision!==1){if(Number.isFinite(saved.dmg))e.dmg=saved.dmg*1.9;for(const h of WILD.hazards)if(h.owner===e)h.damage*=1.9*1.8;e.combatRevision=1;}}if(vendor&&d.vendor){vendor.pastPurchases=d.vendor.pastPurchases||0;if(d.vendor.stockRevision===2){vendor.stockRevision=2;vendor.collections=(Array.isArray(d.vendor.collections)?d.vendor.collections:[]).filter(c=>ARMOR_SETS[c.family]&&Array.isArray(c.ids)).map(c=>({...c,name:ARMOR_SETS[c.family].name,ids:c.ids.filter(id=>vendor.stock.some(r=>r.item.id===id))}));}else{vendor.pastPurchases+=d.vendor.stock.filter(r=>r.sold).length;vendor.stock=makePremiumStock();}}vendorSetFilter=null;markCollisionDirty();};
showTitle=function(){B7.showTitle();const b=$('buildMarker');if(b)b.textContent='RELICS & RECKONING · PRECISE COMBAT';};

validSave=function(d){if(!B7.validSave(d))return false;const v=d.vendor;if(!v||v.stockRevision!==2)return true;if(v.pastPurchases!==undefined&&(!Number.isSafeInteger(v.pastPurchases)||v.pastPurchases<0))return false;if(!Array.isArray(v.collections)||v.collections.length>2)return false;const ids=new Set();return v.collections.every(c=>{if(!c||!ARMOR_SETS[c.family]||!Array.isArray(c.ids)||c.ids.length!==6)return false;const slots=new Set();return c.ids.every(id=>{const row=v.stock.find(r=>r.item.id===id);if(ids.has(id)||!row||row.item.armorSet!==c.family||row.item.slot==='weapon'||slots.has(row.item.slot))return false;ids.add(id);slots.add(row.item.slot);return true;});});};
